#!/usr/bin/env node
// Generated by ai-factory. SubagentStop hook: records each agent's final output
// to .factory/runs/<session>/NN-<agent>.md.
//
// Why: the chain's artifacts currently exist only inside the orchestrator's
// context. Nothing on disk says what the researcher found or what contract the
// backend builder emitted, so a run cannot be audited or resumed — and the
// orchestrator has to carry every prior output forward as inlined text. Writing
// them down is the precondition for passing paths instead. It also brings the
// Claude Code adapter to parity with Codex, whose orchestrators already tee each
// step into .codex/runs/.
//
// Never blocks: this hook only observes, so every path exits 0.
//
// Do not hand-edit — edit .factory.yaml and re-run `factory install`.
import { readFileSync, writeFileSync, mkdirSync, readdirSync } from "node:fs";
import { join } from "node:path";

try {
  let data = {};
  try { data = JSON.parse(readFileSync(0, "utf8") || "{}"); } catch {}
  if (!data || typeof data !== "object") process.exit(0);

  const message = data.last_assistant_message;
  if (typeof message !== "string" || message.trim() === "") process.exit(0);

  const cwd = data.cwd || process.cwd();
  const session = safe(data.session_id) || "session";
  const agent = safe(data.agent_type) || "agent";

  const dir = join(cwd, ".factory", "runs", session);
  mkdirSync(dir, { recursive: true });

  let count = 0;
  try { count = readdirSync(dir).filter((f) => f.endsWith(".md")).length; } catch {}
  const seq = String(count + 1).padStart(2, "0");

  const header = [
    `<!-- ai-factory run artifact -->`,
    `<!-- agent: ${agent} -->`,
    `<!-- agent_id: ${safe(data.agent_id) || "unknown"} -->`,
    `<!-- recorded: ${new Date().toISOString()} -->`,
    "",
  ].join("\n");

  writeFileSync(join(dir, `${seq}-${agent}.md`), header + message + "\n");
} catch {
  // Never let a recording failure interfere with the session.
}
process.exit(0);

/** Keep ids and agent names safe to use as path segments. */
function safe(value) {
  if (typeof value !== "string") return "";
  return value.replace(/[^A-Za-z0-9._-]/g, "-").replace(/^[.-]+/, "").slice(0, 64);
}
